def _build_chain():
    events = []
    previous = None
    for index, intent in enumerate(INTENTS, 1):
        provisional = AuthorityEvent(
            f"018cc251-f400-7000-8000-{index:012d}", index, previous, intent, NOW,
            "", "sha256:" + "0" * 64,
        )
        signature = sign(KEY, event_unsigned_bytes(provisional))
        signed = AuthorityEvent(
            provisional.event_id, provisional.sequence, provisional.previous_event_hash,
            provisional.intent, provisional.recorded_at_utc, signature, "sha256:" + "0" * 64,
        )
        complete = AuthorityEvent(
            signed.event_id, signed.sequence, signed.previous_event_hash,
            signed.intent, signed.recorded_at_utc, signed.signature, event_hash(signed),
        )
        events.append(complete)
        previous = complete.event_hash
    return events


@pytest.mark.parametrize("intent,expected", list(zip(INTENTS, EXPECTED.values())), ids=list(EXPECTED))
def test_signed_bytes_of_the_six_historical_types_are_pinned_to_master(intent, expected):
    event = next(item for item in _build_chain() if item.intent is intent)
    expected_unsigned, expected_signature, expected_hash = expected
    assert event_unsigned_bytes(event).hex() == expected_unsigned
    assert event.signature == expected_signature
    assert event.event_hash == expected_hash


def test_golden_chain_genesis_is_deterministic():
    assert genesis_hash(GENESIS) == "sha256:55fa9ab7b6036d65822ae7e129d1955ae72ce8d305034a37146fcbe22a0b6395"
